# Group 3 Cortech tabs, batch 2 (Nov 12). Loaded by mc4.py after ../pc.py, ../g2/pc2.py, ../g3/pc3.py (constants).
P=[]
def add(**k): P.append(k)
SEAT=CP+'furniture/seating/'
FL='**Flammability Standards:** Flame retardant; passes California Technical Bulletin 133'
NOWAR='Warranty: your current page does not list a warranty. The Cortech spec sheet says lifetime warranty against manufacturing defects, so I added it.'
PRE='**Pilot Holes:** Cortech advises not to pre-drill pilot holes until the desk is on site and ready to install'
ADA_APPS=['Accessible cells and housing units in correctional facilities and jails','Accessible patient rooms in behavioral healthcare facilities and psychiatric hospitals','Residential treatment centers and other rooms that need an ADA-compliant desk']
WS_APPS=['Cells and housing units in correctional facilities and jails','Patient rooms in behavioral healthcare facilities and psychiatric hospitals','Compact rooms and study areas where floor space is limited']
CREW_APPS=['Dining halls and dayrooms in correctional facilities and jails','Group rooms and dayrooms in behavioral healthcare facilities and psychiatric hospitals','Residential treatment centers and other group spaces']
def crew_name(n): return (f'Name: Cortech now calls it the {n}, without "Endurance." I kept "Endurance" as on your current page and in your page address. Would you like it removed?')
CREW_KT=('Floor bracket: the Cortech bolt-down drawing shows a 12-gauge floor bracket that attaches to the chair with two 5/16”-18×¾” tamper-resistant Torx flat head screws. I used this in the Installation section.')
def crew_s(m): return (f'{m}S (with access door): the current Cortech spec sheet lists only the standard {m} and the optional bolt-down kit. It does not list a model with an access door. I kept your variant. Can you check that it is still available?')

# 1. 136484 Bench
